<?php
require_once '../../config/auth.php';
require_once '../../config/database.php';
requireRole('admin');

$academicYears = $pdo->query("SELECT id, tahun_ajaran, status FROM academic_years ORDER BY tanggal_mulai DESC")->fetchAll(PDO::FETCH_ASSOC);
$selectedYearId = (int) ($_GET['academic_year_id'] ?? 0);
if (!$selectedYearId) { foreach ($academicYears as $year) { if ($year['status'] === 'aktif') { $selectedYearId = (int) $year['id']; break; } } }
$stmt = $pdo->prepare("SELECT om.id, om.student_id, om.position_id, om.academic_year_id, om.tanggal_mulai, om.tanggal_selesai, om.status, s.nama_lengkap, COALESCE(ch.nama_kelas, c.nama_kelas) AS nama_kelas, COALESCE(ch.jurusan, c.jurusan) AS jurusan, COALESCE(NULLIF(d.singkatan, ''), COALESCE(ch.jurusan, c.jurusan), '') AS jurusan_singkat, op.nama_jabatan, ay.tahun_ajaran FROM osis_members om INNER JOIN students s ON s.id = om.student_id LEFT JOIN student_class_history sch ON sch.student_id = om.student_id AND sch.academic_year_id = om.academic_year_id AND sch.status = 'aktif' LEFT JOIN classes ch ON ch.id = sch.class_id INNER JOIN classes c ON c.id = s.kelas_id INNER JOIN osis_positions op ON op.id = om.position_id INNER JOIN academic_years ay ON ay.id = om.academic_year_id LEFT JOIN departments d ON d.nama_jurusan = COALESCE(ch.jurusan, c.jurusan) WHERE om.academic_year_id = ? AND om.status NOT IN ('keluar', 'lulus') ORDER BY CASE WHEN om.status = 'menunggu' THEN 1 WHEN om.status = 'aktif' THEN 2 ELSE 3 END, om.id DESC");
$stmt->execute([$selectedYearId]);
$anggota = $stmt->fetchAll(PDO::FETCH_ASSOC);
$totalAnggota = count($anggota);
$aktif = count(array_filter($anggota, static fn($row) => $row['status'] === 'aktif'));
$menunggu = count(array_filter($anggota, static fn($row) => $row['status'] === 'menunggu'));
$totalJabatan = count(array_unique(array_filter(array_column($anggota, 'nama_jabatan'))));
$pageTitle = 'Anggota OSIS';
require_once '../../includes/header.php';
require_once '../../includes/sidebar.php';
?>
