        <section class="member-list-card"><div class="member-list-head"><div><span class="eyebrow">Daftar keanggotaan</span><h4>Anggota dan jabatan OSIS</h4><p><?= $menunggu > 0 ? $menunggu . ' pendaftaran sedang menunggu penentuan jabatan.' : 'Semua pendaftaran telah ditinjau.' ?></p></div><div class="member-search"><i class="bi bi-search"></i><input type="search" id="memberSearch" placeholder="Cari nama, kelas, atau jurusan..."></div></div><form method="get" class="p-3 border-top"><label class="form-label small">Tahun ajaran</label><select name="academic_year_id" class="form-select" style="max-width:280px" onchange="this.form.submit()"><?php foreach ($academicYears as $year): ?><option value="<?= (int) $year['id'] ?>" <?= $selectedYearId === (int) $year['id'] ? 'selected' : '' ?>><?= htmlspecialchars($year['tahun_ajaran']) ?><?= $year['status'] === 'aktif' ? ' (aktif)' : '' ?></option><?php endforeach; ?></select></form><div class="table-responsive"><table class="table member-modern-table align-middle mb-0"><thead><tr><th>No.</th><th>Anggota</th><th>Kelas / Jurusan</th><th>Jabatan</th><th>Tahun ajaran</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody id="memberTableBody">
            <?php foreach ($anggota as $index => $row): ?><tr data-search="<?= htmlspecialchars(strtolower($row['nama_lengkap'] . ' ' . $row['nama_kelas'] . ' ' . $row['jurusan_singkat'] . ' ' . $row['nama_jabatan'])) ?>"><td class="member-row-number"><?= $index + 1 ?></td><td><div class="member-profile-cell"><span class="member-avatar"><?= htmlspecialchars(strtoupper(substr($row['nama_lengkap'], 0, 1))) ?></span><strong><?= htmlspecialchars($row['nama_lengkap']) ?></strong></div></td><td><strong><?= htmlspecialchars($row['nama_kelas']) ?></strong><?php if ($row['jurusan_singkat'] !== ''): ?><small class="d-block member-department"><i class="bi bi-building"></i> <?= htmlspecialchars($row['jurusan_singkat']) ?></small><?php endif; ?></td><td><?php if ($row['status'] === 'menunggu'): ?><span class="member-position pending"><i class="bi bi-question-circle"></i> Belum ditentukan</span><?php else: ?><span class="member-position"><i class="bi bi-award"></i> <?= htmlspecialchars($row['nama_jabatan']) ?></span><?php endif; ?></td><td><?= htmlspecialchars($row['tahun_ajaran']) ?></td><td><span class="member-status <?= htmlspecialchars($row['status']) ?>"><i class="bi bi-circle-fill"></i><?= $row['status'] === 'menunggu' ? 'Menunggu' : htmlspecialchars(ucfirst($row['status'])) ?></span></td><td class="text-end"><div class="member-action-group"><?php if ($row['status'] === 'menunggu'): ?><a href="tentukan_jabatan.php?id=<?= (int) $row['id'] ?>" class="btn btn-sm btn-success" title="Tentukan jabatan"><i class="bi bi-person-check"></i><span class="member-action-label"> Jabatan</span></a><form action="verifikasi.php" method="post" class="d-inline" onsubmit="return confirm('Tolak pendaftaran OSIS ini?');"><input type="hidden" name="id" value="<?= (int) $row['id'] ?>"><button type="submit" name="action" value="tolak" class="btn btn-sm btn-light text-danger" title="Tolak pendaftaran"><i class="bi bi-x-lg"></i></button></form><?php else: ?><form action="ubah_status.php" method="post" class="d-inline"><input type="hidden" name="id" value="<?= (int) $row['id'] ?>"><div class="btn-group btn-group-sm"><button type="submit" name="status" value="aktif" class="btn btn-success" title="Aktifkan / perpanjang aktif"><i class="bi bi-check-lg"></i></button><button type="submit" name="status" value="nonaktif" class="btn btn-warning" title="Nonaktif sementara / PKL"><i class="bi bi-pause-fill"></i></button><button type="submit" name="status" value="keluar" class="btn btn-outline-danger" title="Keluar" onclick="return confirm('Tandai anggota ini keluar dari OSIS?');"><i class="bi bi-box-arrow-right"></i></button><button type="submit" name="status" value="lulus" class="btn btn-secondary" title="Lulus" onclick="return confirm('Tandai anggota ini lulus?');"><i class="bi bi-mortarboard-fill"></i></button></div></form><a href="edit.php?id=<?= (int) $row['id'] ?>" class="btn btn-sm btn-light text-primary" title="Edit jabatan dan periode"><i class="bi bi-pencil-square"></i></a><?php endif; ?><a href="hapus.php?id=<?= (int) $row['id'] ?>" class="btn btn-sm btn-light text-danger" title="Hapus anggota" onclick="return confirm('Yakin ingin menghapus anggota OSIS ini?');"><i class="bi bi-trash"></i></a></div></td></tr><?php endforeach; ?>
            <?php if (!$anggota): ?><tr><td colspan="7" class="text-center text-muted py-5"><i class="bi bi-people d-block fs-2 mb-2"></i>Belum ada anggota OSIS.</td></tr><?php endif; ?><tr id="memberNotFound" class="d-none"><td colspan="7" class="text-center text-muted py-5"><i class="bi bi-search d-block fs-3 mb-2"></i>Anggota tidak ditemukan.</td></tr>
        </tbody></table></div></section>
