<script>
document.getElementById('memberSearch')?.addEventListener('input', function () { const keyword = this.value.trim().toLowerCase(); const rows = Array.from(document.querySelectorAll('#memberTableBody tr[data-search]')); let found = 0; rows.forEach(row => { const visible = row.dataset.search.includes(keyword); row.classList.toggle('d-none', !visible); if (visible) found++; }); document.getElementById('memberNotFound')?.classList.toggle('d-none', found !== 0 || keyword === ''); });
document.querySelectorAll('form[action="ubah_status.php"] .btn-group > button:first-child').forEach(button => button.addEventListener('click', event => { const group = button.closest('.btn-group'); if (!group.classList.contains('is-open')) { event.preventDefault(); document.querySelectorAll('form[action="ubah_status.php"] .btn-group.is-open').forEach(item => item.classList.remove('is-open')); group.classList.add('is-open'); } }));
document.addEventListener('click', event => { if (!event.target.closest('form[action="ubah_status.php"]')) document.querySelectorAll('form[action="ubah_status.php"] .btn-group.is-open').forEach(item => item.classList.remove('is-open')); });
</script>
